// Resilience4j circuit breaker configuration
CircuitBreakerConfig config = CircuitBreakerConfig.custom()
    .slidingWindowType(SlidingWindowType.TIME_BASED)
    .slidingWindowSize(10)                           // 10-second window
    .failureRateThreshold(50)                        // trip at 50% errors
    .slowCallRateThreshold(50)                       // also trip at 50% slow calls
    .slowCallDurationThreshold(Duration.ofSeconds(2))
    .waitDurationInOpenState(Duration.ofSeconds(30)) // stay open 30 s
    .permittedNumberOfCallsInHalfOpenState(3)        // 3 probes in half-open
    .recordExceptions(IOException.class, TimeoutException.class)
    .ignoreExceptions(BadRequestException.class)     // don't count 400s
    .build();

CircuitBreaker breaker = CircuitBreakerRegistry.of(config)
    .circuitBreaker("payment-service");

// Decorate the downstream call
Supplier<PaymentResult> decorated = CircuitBreaker
    .decorateSupplier(breaker, () -> paymentClient.charge(request));

try {
    return decorated.get();
} catch (CallNotPermittedException e) {
    return fallbackResponse(); // circuit is OPEN — fast fail
}

// Resilience4j thread-pool bulkhead per downstream
ThreadPoolBulkheadConfig config = ThreadPoolBulkheadConfig.custom()
    .maxThreadPoolSize(15)       // max concurrent calls to this dependency
    .coreThreadPoolSize(10)
    .queueCapacity(50)           // queue before rejecting
    .keepAliveDuration(Duration.ofMillis(20))
    .build();

ThreadPoolBulkhead bulkhead = ThreadPoolBulkheadRegistry
    .of(config)
    .bulkhead("fraud-service");

// Decorate a call to fraud service
CompletableFuture<FraudResult> future = bulkhead
    .executeSupplier(() -> fraudClient.check(order));

// If fraud-service is slow, only its 15 threads fill up.
// Payments and Inventory use separate bulkheads → unaffected.

