# Saga orchestrator pseudocode for Order placement
class CreateOrderSaga:
    steps = [
        SagaStep(
            action=lambda ctx: payment_svc.reserve(ctx.order_id, ctx.amount),
            compensation=lambda ctx: payment_svc.cancel(ctx.payment_id)
        ),
        SagaStep(
            action=lambda ctx: inventory_svc.reserve(ctx.items),
            compensation=lambda ctx: inventory_svc.release(ctx.reservation_id)
        ),
        SagaStep(
            action=lambda ctx: shipping_svc.schedule(ctx.order_id),
            compensation=lambda ctx: shipping_svc.cancel(ctx.shipment_id)
        ),
    ]

    def execute(self, ctx):
        completed = []
        for step in self.steps:
            try:
                step.action(ctx)
                completed.append(step)
            except Exception:
                # run compensations in reverse
                for done in reversed(completed):
                    done.compensation(ctx)
                raise SagaRolledBack()

# Inventory service: choreography participant
@kafka_consumer(topic="payment.reserved")
def on_payment_reserved(event):
    order_id = event["orderId"]
    items    = event["items"]
    try:
        reservation = inventory.reserve(order_id, items)
        kafka.publish("inventory.reserved", {
            "orderId": order_id,
            "reservationId": reservation.id,
        })
    except InsufficientStockError:
        kafka.publish("inventory.reservation.failed", {
            "orderId": order_id,
            "reason": "INSUFFICIENT_STOCK",
        })

# Payment service: listens for failure and compensates
