def on_inventory_failed(event):
    payment.cancel(event["orderId"])  # compensating transaction

# Temporal workflow: orchestrated Create Order saga
from temporalio import workflow, activity

@workflow.defn
class CreateOrderSaga:
    @workflow.run
    async def run(self, order: OrderInput) -> str:
        # Step 1: reserve payment
        payment_id = await workflow.execute_activity(
            reserve_payment,
            order.amount,
            schedule_to_close_timeout=timedelta(seconds=30),
        )
        # Step 2: reserve inventory
        try:
            reservation_id = await workflow.execute_activity(
                reserve_inventory, order.items,
                schedule_to_close_timeout=timedelta(seconds=30),
            )
        except Exception:
            # Compensation: cancel payment
            await workflow.execute_activity(cancel_payment, payment_id)
            raise
        return reservation_id

