-- Inbox pattern: idempotent consumer with transactional deduplication
BEGIN;
  -- Attempt to record this message ID
  -- If duplicate: constraint violation → silent skip via ON CONFLICT
  INSERT INTO inbox_events (message_id, event_type, payload)
    VALUES ($message_id, $event_type, $payload)
    ON CONFLICT (message_id) DO NOTHING;

  -- Only execute business logic if the insert produced a new row
  -- (PostgreSQL: GET DIAGNOSTICS rows_affected = ROW_COUNT)
  IF rows_affected = 1 THEN
    -- Business logic here: upsert inventory, update order status, etc.
    INSERT INTO shipments (order_id, status)
      VALUES ($order_id, 'SCHEDULED')
      ON CONFLICT (order_id) DO NOTHING;
  END IF;
COMMIT;
